function modelFile = tepadsim_build_model(varargin)
%TEPADSIM_BUILD_MODEL Builds the TEPAD PV dual-stream simulation model programmatically (the .slx is generated by this script).
%
%   modelFile = tepadsim_build_model            % returns immediately when it exists and 'force' is not given
%   modelFile = tepadsim_build_model('force', true)
%   modelFile = tepadsim_build_model('openAfter', true)
%
%   Why build the model with a script: .slx is a compressed binary container — unmaintainable by hand and undiffable;
%   putting the topology in code means reviews read the structure and structural edits change the same text.
%
%   Model topology (one flat diagram, no nested subsystems):
%
%     Plant Params ─┐
%                   ├─► PV Plant ──┐                     (online generation path)
%     Plant State ──┘              │
%                                  ├─► Source Switch ─► Split Measurement
%     Replay Source ───────────────┘        (replayMode)      │
%                                                     g│ p│ pNormal│ sigma│ tick
%                             tick==spikeAt ─► Spike Switch ◄── p+sigma*spikeSigma
%                             tick∈[shadeFrom,shadeTo) ─► Shade Switch ◄── p*shadeFactor
%                                              │
%                       g ─┐                   ▼
%                          ├─► TEPAD Detector ◄─ Calibration
%                     p ───┘        │  └─► Detector State(Unit Delay, 1x153)
%                                   ▼
%                          Split Result ─► Log Mux ─► To Workspace / Scope
%
%   The code of the two MATLAB Function blocks (detector and PV model) is injected by
%   fileread from tepadsim_detector_step.m / tepadsim_plant_step.m,
%   so "the algorithm inside the model" and "the algorithm in the command-line self-test" are always the same text.
%
%   Every adjustable quantity (tick count, seed, injection parameters, calibration) lives in the three base workspace structs
%   tepadsimScenario / tepadsimFault / tepadsimCalib, placed there by tepadsim_init,
%   so changing the scenario needs no model edit.

cfg = tepadsim_setup_path();
force = false;
openAfter = false;
for k = 1:2:numel(varargin)
    switch lower(varargin{k})
        case 'force', force = logical(varargin{k + 1});
        case 'openAfter', openAfter = logical(varargin{k + 1});
    end
end

modelFile = cfg.modelFile;
if exist(modelFile, 'file') == 2 && ~force
    fprintf('model already exists, skipping the build: %s (pass force=true to rebuild)\n', modelFile);
    return;
end

if exist(cfg.modelDir, 'dir') ~= 7
    mkdir(cfg.modelDir);
end

name = cfg.modelName;
if bdIsLoaded(name)
    % If Dirty is not cleared, close_system pops an interactive confirmation and hangs outright in -batch mode.
    set_param(name, 'Dirty', 'off');
    close_system(name, 0);
end
new_system(name);

% ---- solver: 1 step = 1 tick = 1 minute (config.SIMULATION_TICK_MINUTES) ------
set_param(name, ...
    'Solver', 'FixedStepDiscrete', ...
    'FixedStep', '1', ...
    'StopTime', num2str(cfg.ticksPerDay - 1), ...
    'StartTime', '0', ...
    'SaveOutput', 'off', ...
    'SaveLog', 'off');

% ---- model callbacks: prepare path and workspace variables on load/run ------
set_param(name, ...
    'PreLoadFcn', 'tepadsim_init;', ...
    'InitFcn', 'tepadsim_init; tepadsim_apply_model_config;');

% ---- data source: online PV model / workspace replay ----------------------
add_block('simulink/Sources/Constant', [name '/Plant Params'], ...
    'Value', 'tepadsimScenario.plantParams', ...
    'Position', local_xy(40, 60));
add_block('simulink/Discrete/Unit Delay', [name '/Plant State'], ...
    'InitialCondition', 'tepadsimScenario.plantState0(:)', ...
    'SampleTime', '1', ...
    'Position', local_xy(40, 170));
local_matlab_function(name, 'PV Plant', fullfile(cfg.srcDir, 'tepadsim_plant_step.m'), ...
    local_xy(180, 90));

% SampleTime='0' makes the block sample along the timeseries' own time axis (1 tick = 1 step),
% Interpolate='on' + 'Holding final value': after the data runs out the last value is held, never extrapolated.
add_block('simulink/Sources/From Workspace', [name '/Replay Source'], ...
    'VariableName', 'tepadsimScenario.replay', ...
    'SampleTime', '0', ...
    'Interpolate', 'on', ...
    'OutputAfterFinalValue', 'Holding final value', ...
    'Position', local_xy(40, 260));

add_block('simulink/Signal Routing/Switch', [name '/Source Switch'], ...
    'Criteria', 'u2 ~= 0', ...
    'Position', local_xy(360, 170));
add_block('simulink/Sources/Constant', [name '/Replay Mode'], ...
    'Value', 'tepadsimScenario.replayMode', ...
    'Position', local_xy(360, 300));

% meas = [g p pNormal sigma tick]
% 'Outputs' takes the scalar count 5 rather than '[1 1 1 1 1]': the latter turns every output into a [1x1] matrix,
%   which the MATLAB Function scalar ports reject (measured: "port width mismatch").
add_block('simulink/Signal Routing/Demux', [name '/Split Measurement'], ...
    'Outputs', '5', ...
    'Position', local_xy(500, 110));

% ---- fault injection (equivalent to the two "manual injection" buttons on the sim_ui screen) ----
add_block('simulink/Logic and Bit Operations/Relational Operator', [name '/Spike Trigger'], ...
    'Operator', '==', 'Position', local_xy(640, 40));
add_block('simulink/Sources/Constant', [name '/Spike At'], ...
    'Value', 'tepadsimFault.spikeAt', ...
    'Position', local_xy(640, 120));
add_block('simulink/Math Operations/Product', [name '/Spike Amp'], ...
    'Inputs', '2', 'Position', local_xy(760, 150));
add_block('simulink/Sources/Constant', [name '/Spike Sigma'], ...
    'Value', 'tepadsimFault.spikeSigma', ...
    'Position', local_xy(760, 230));
add_block('simulink/Math Operations/Sum', [name '/Spike Sum'], ...
    'Inputs', '++', 'Position', local_xy(880, 170));
add_block('simulink/Signal Routing/Switch', [name '/Spike Switch'], ...
    'Criteria', 'u2 ~= 0', 'Position', local_xy(1000, 120));

add_block('simulink/Logic and Bit Operations/Relational Operator', [name '/Shade From'], ...
    'Operator', '>=', 'Position', local_xy(640, 300));
add_block('simulink/Sources/Constant', [name '/Shade From At'], ...
    'Value', 'tepadsimFault.shadeFrom', ...
    'Position', local_xy(640, 380));
add_block('simulink/Logic and Bit Operations/Relational Operator', [name '/Shade To'], ...
    'Operator', '<', 'Position', local_xy(780, 300));
add_block('simulink/Sources/Constant', [name '/Shade To At'], ...
    'Value', 'tepadsimFault.shadeTo', ...
    'Position', local_xy(780, 380));
add_block('simulink/Logic and Bit Operations/Logical Operator', [name '/Shade Mask'], ...
    'Operator', 'AND', 'Inputs', '2', 'Position', local_xy(920, 300));
add_block('simulink/Math Operations/Product', [name '/Shade Amp'], ...
    'Inputs', '2', 'Position', local_xy(1040, 320));
add_block('simulink/Sources/Constant', [name '/Shade Factor'], ...
    'Value', 'tepadsimFault.shadeFactor', ...
    'Position', local_xy(1040, 400));
add_block('simulink/Signal Routing/Switch', [name '/Shade Switch'], ...
    'Criteria', 'u2 ~= 0', 'Position', local_xy(1160, 170));

% ---- dual-window detector -------------------------------------------------
add_block('simulink/Sources/Constant', [name '/Calibration'], ...
    'Value', 'tepadsimCalib.packed', ...
    'Position', local_xy(1160, 40));
add_block('simulink/Discrete/Unit Delay', [name '/Detector State'], ...
    'InitialCondition', sprintf('zeros(%d,1)', cfg.stateDim), ...
    'SampleTime', '1', ...
    'Position', local_xy(1160, 460));
local_matlab_function(name, 'TEPAD Detector', ...
    fullfile(cfg.srcDir, 'tepadsim_detector_step.m'), local_xy(1300, 150));

add_block('simulink/Signal Routing/Demux', [name '/Split Result'], ...
    'Outputs', '7', 'Position', local_xy(1460, 120));

% ---- logging and observation ----------------------------------------------
add_block('simulink/Signal Routing/Mux', [name '/Log Mux'], ...
    'Inputs', '9', 'Position', local_xy(1600, 260));
add_block('simulink/Sinks/To Workspace', [name '/Log'], ...
    'VariableName', 'tepadsimLog', ...
    'SaveFormat', 'Array', ...
    'MaxDataPoints', 'inf', ...
    'Position', local_xy(1720, 250));
add_block('simulink/Sinks/Scope', [name '/Overview Scope'], ...
    'NumInputPorts', '1', 'ShowLegend', 'on', ...
    'Position', local_xy(1720, 340));

% ---- wiring ----------------------------------------------------------------
local_line(name, 'Plant Params/1', 'PV Plant/1');
local_line(name, 'Plant State/1', 'PV Plant/2');
local_line(name, 'PV Plant/1', 'Source Switch/3');      % online generation uses the lower input (replayMode=0)
local_line(name, 'PV Plant/2', 'Plant State/1');
local_line(name, 'Replay Source/1', 'Source Switch/1'); % replay uses the upper input (selected when replayMode~=0)
local_line(name, 'Replay Mode/1', 'Source Switch/2');
local_line(name, 'Source Switch/1', 'Split Measurement/1');

% Split Measurement: 1=g 2=p 3=pNormal 4=sigma 5=tick
local_line(name, 'Split Measurement/5', 'Spike Trigger/1');
local_line(name, 'Spike At/1', 'Spike Trigger/2');
local_line(name, 'Split Measurement/4', 'Spike Amp/1');
local_line(name, 'Spike Sigma/1', 'Spike Amp/2');
local_line(name, 'Spike Amp/1', 'Spike Sum/2');
local_line(name, 'Split Measurement/2', 'Spike Sum/1');
local_line(name, 'Spike Sum/1', 'Spike Switch/1');
local_line(name, 'Split Measurement/2', 'Spike Switch/3');
local_line(name, 'Spike Trigger/1', 'Spike Switch/2');

local_line(name, 'Split Measurement/5', 'Shade From/1');
local_line(name, 'Shade From At/1', 'Shade From/2');
local_line(name, 'Split Measurement/5', 'Shade To/1');
local_line(name, 'Shade To At/1', 'Shade To/2');
local_line(name, 'Shade From/1', 'Shade Mask/1');
local_line(name, 'Shade To/1', 'Shade Mask/2');
local_line(name, 'Spike Switch/1', 'Shade Amp/1');
local_line(name, 'Shade Factor/1', 'Shade Amp/2');
local_line(name, 'Shade Amp/1', 'Shade Switch/1');
local_line(name, 'Spike Switch/1', 'Shade Switch/3');
local_line(name, 'Shade Mask/1', 'Shade Switch/2');

local_line(name, 'Split Measurement/1', 'TEPAD Detector/1');   % g
local_line(name, 'Shade Switch/1', 'TEPAD Detector/2');        % p after injection
local_line(name, 'Calibration/1', 'TEPAD Detector/3');
local_line(name, 'Detector State/1', 'TEPAD Detector/4');
local_line(name, 'TEPAD Detector/2', 'Detector State/1');
local_line(name, 'TEPAD Detector/1', 'Split Result/1');

% Split Result: 1=score 2=alarm 3=pointZ 4=ms 5=ml 6=readyS 7=readyL
local_line(name, 'Split Measurement/5', 'Log Mux/1');
local_line(name, 'Split Measurement/1', 'Log Mux/2');
local_line(name, 'Shade Switch/1', 'Log Mux/3');
local_line(name, 'Split Measurement/3', 'Log Mux/4');
local_line(name, 'Split Result/1', 'Log Mux/5');
local_line(name, 'Split Result/2', 'Log Mux/6');
local_line(name, 'Split Result/3', 'Log Mux/7');
local_line(name, 'Split Result/4', 'Log Mux/8');
local_line(name, 'Split Result/5', 'Log Mux/9');
local_line(name, 'Log Mux/1', 'Log/1');
local_line(name, 'Log Mux/1', 'Overview Scope/1');

% ---- annotation: leave a note on the diagram so later readers need not dig through the script ----
local_note(name, ['TEPAD dual-window detector Simulink reproduction: 1 step = 1 tick = 1 minute. ' ...
    'Algorithm source = simulink/src/tepadsim_detector_step.m (line-by-line aligned with src/simulation/model.py). ' ...
    'Data source: PV Plant (online Beta cloud + PVWatts) or Replay Source (workspace replay, used by the golden check). ' ...
    'Injection: Spike Switch (single frame +kσ) / Shade Switch (interval ×factor); parameters live in tepadsimFault.'], ...
    [40 520 1560 570]);

save_system(name, modelFile);
set_param(name, 'Dirty', 'off');
close_system(name, 0);
fprintf('model generated: %s\n', modelFile);

if openAfter
    load_system(modelFile);
    open_system(modelFile);
end
end

% =========================================================================

function pos = local_xy(x, y)
pos = [x y x + 90 y + 46];
end

function local_line(model, fromSpec, toSpec)
add_line(model, fromSpec, toSpec, 'autorouting', 'on');
end

function local_note(model, text, pos)
%LOCAL_NOTE Adds an annotation to the diagram so reviewers can follow the topology without opening the script.
ann = Simulink.Annotation(model, text);
ann.Position = pos;
try
    ann.HorizontalAlignment = 'left';
catch
    % Older/non-English releases may lack this property; the annotation is still on the diagram either way.
end
end

function local_matlab_function(model, blockName, sourceFile, pos)
%LOCAL_MATLAB_FUNCTION Creates a MATLAB Function block and injects the .m source verbatim into it.
%   The block ports are derived from the function signature, so changing the signature in the .m changes the block interface — no second definition.
blk = [model '/' blockName];
add_block('simulink/User-Defined Functions/MATLAB Function', blk, 'Position', pos);
cfgObj = get_param(blk, 'MATLABFunctionConfiguration');
cfgObj.FunctionScript = fileread(sourceFile);
end
